def inline(s):
    s=html.escape(s)
    s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',r'<a href="\2">\1</a>',s)
    s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
    s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
    return s

def markdown(text):
    lines=text.splitlines(); out=[]; i=0; para=[]; inlist=False
    def flush():
        if para: out.append('<p>'+inline(' '.join(para))+'</p>'); para.clear()
    while i<len(lines):
        l=lines[i]
        if not l.strip():
            flush()
            if inlist: out.append('</ul>'); inlist=False
            i+=1; continue
        if l.startswith('|'):
            flush(); rows=[]
            while i<len(lines) and lines[i].startswith('|'):
                row=lines[i]
                if not re.match(r'^\|[\s:|\-]+\|$',row): rows.append([x.strip() for x in row.strip('|').split('|')])
                i+=1
            out.append('<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+inline(x)+'</th>' for x in rows[0])+'</tr></thead><tbody>')
            out.extend('<tr>'+''.join('<td>'+inline(x)+'</td>' for x in row)+'</tr>' for row in rows[1:]); out.append('</tbody></table></div>'); continue
        m=re.match(r'^(#{1,4}) (.*)',l)
        if m:
            flush(); level=min(len(m[1])+1,5); out.append(f'<h{level}>'+inline(m[2])+f'</h{level}>')
        elif re.match(r'^(?:- |\d+\. )',l):
            flush()
            if not inlist: out.append('<ul>'); inlist=True
            out.append('<li>'+inline(re.sub(r'^(?:- |\d+\. )','',l))+'</li>')
        else: para.append(l)
        i+=1
    flush()
    if inlist:out.append('</ul>')
    return '\n'.join(out)

